def separate_paren_groups(paren_string: str) -> List[str]:
    result: List[str] = []
    depth = 0
    current = ""
    for ch in paren_string:
        if ch == " ":
            continue
        if ch not in "()" :
            continue
        if ch == "(":
            if depth == 0:
                current = ""
            depth += 1
        if depth > 0:
            current += ch
