def cantor_numbering(N: int) -> str:
    """Return the N-th fraction in Cantor's table."""
    lo, hi = 1, N
    while lo < hi:
        mid = (lo + hi) // 2
        if mid * (mid + 1) // 2 >= N:
            hi = mid
        else:
            lo = mid + 1
    d = lo
    prev_cum = (d - 1) * d // 2
    offset = N - prev_cum - 1
    if d % 2 == 0:
        numerator = 1 + offset
        denominator = d - offset
    else:
        numerator = d - offset
        denominator = 1 + offset
    return f"{numerator}/{denominator}"

