    * Every character of `message` must be present in the mapping.

    If any of these constraints fail, the function returns "Failed".

    Args:
        encoded (str): A string representing the encoded information.
        original (str): A string representing the original information corresponding
                        to the encoded string.
        message (str): A string representing the encrypted message to be decoded.

    Returns:
        str: The decoded message if successful, otherwise "Failed".
    """
    # Validate lengths
    if len(encoded) != len(original):
        return "Failed"

    mapping: dict[str, str] = {}
    reverse: dict[str, str] = {}

    # Build mapping
    for e_char, o_char in zip(encoded, original):
        # If the encoded character already has an assigned mapping, ensure it matches.
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char
        # Ensure that two encoded characters don't map to the same original character.
        if o_char in reverse:
            if reverse[o_char] != e_char:
                return "Failed"
        else:
            reverse[o_char] = e_char

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return ''.join(decoded_chars)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Args:
        encoded: A string representing the encoded information.
        original: A string representing the original information corresponding to the encoded string.
        message: A string representing the encrypted message to be decoded.

    Returns:
        The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Both strings must be of equal length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                # Contradiction found
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    # Mapping must contain all 26 letters
    if len(mapping) != 26:
        return "Failed"

    try:
        decoded = ''.join(mapping[ch] for ch in message)
    except KeyError:
        # If any message character isn't in the mapping
        return "Failed"

    return decoded

def largest_prime_factor(n: int) -> int:
    """
    Returns the larger of the two distinct prime factors of a positive integer n.
    Assumes n is the product of exactly two distinct primes.
    """
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i = i + 1 if i == 2 else i + 2  # skip even numbers after 2
