def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs of positive integers (P, Q) such that
    GCD(P, Q) == x0 and LCM(P, Q) == y0.

    Parameters:
        x0 (int): The common divisor that each pair (P, Q) must share.
        y0 (int): The least common multiple that each pair (P, Q) must have.

    Returns:
        int: The number of ordered pairs (P, Q) satisfying the conditions.
    """
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    n = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            if _gcd(i, j) == 1:
                if i == j:
                    total += 1
                else:
                    total += 2
        i += 1
    return total

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0
    q = y0 // x0
    from math import gcd, isqrt
    count = 0
    for a in range(1, isqrt(q) + 1):
        if q % a == 0:
            b = q // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

