def generate_numbers(n, rules) -> int:
    # Build adjacency list for digit transformations
    from collections import defaultdict, deque
    adjacency = defaultdict(list)
    for x, y in rules:
        adjacency[ str(x) ].append(str(y))

    # Function to compute all reachable digits from a single starting digit
    def reachable(start):
        seen = set([start])
        q = deque([start])
        while q:
            cur = q.popleft()
            for nxt in adjacency.get(cur, []):
                if nxt not in seen:
                    seen.add(nxt)
                    q.append(nxt)
        return seen

    # For each digit in the original number, compute reachable digits
    digits = str(n)
    result = 1
    for d in digits:
        result *= len(reachable(d))
    return result

def calculate_score(system: int, points: str) -> list:
    """Calculate ping-pong game scores according to the given system."""
    scores = []
    player = 0
    opponent = 0
    for pt in points:
        if pt == 'W':
            player += 1
        elif pt == 'L':
            opponent += 1
        else:
            continue  # ignore any other characters

        # Check if a game is finished
        if player >= system or opponent >= system:
            diff = player - opponent
            if diff >= 2:
                scores.append(f"{player}:{opponent}")
                player, opponent = 0, 0
            elif diff <= -2:
                scores.append(f"{player}:{opponent}")
                player, opponent = 0, 0

    # If there is an unfinished game, add its current score
    if player != 0 or opponent != 0:
        scores.append(f"{player}:{opponent}")

    return scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    catalan = [1] * (n + 1)
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += catalan[j] * catalan[i - 1 - j]
        catalan[i] = total
    return catalan[n]

