    dp = [0] * (T + 1)
    for time_cost, value in herbs:
        if time_cost > T:
            continue
        for t in range(T, time_cost - 1, -1):
            potential = dp[t - time_cost] + value
            if potential > dp[t]:
                dp[t] = potential
    return dp[T]

def calculate_arrangements(n, m, a) -> int:
    mod = 10**6 + 7
    # Edge case: if total capacity less than m, no arrangements
    if sum(a) < m:
        return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for max_k in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for i in range(1, m + 1):
            prefix[i] = (prefix[i-1] + dp[i]) % mod
        new_dp = [0] * (m + 1)
        for k in range(m + 1):
            left = k - max_k
            if left <= 0:
                new_dp[k] = prefix[k]
            else:
                new_dp[k] = (prefix[k] - prefix[left - 1]) % mod
        dp = new_dp
    return dp[m] % mod

def calculate_arrangements(n, m, a) -> int:
    MOD = 1000007
    dp = [0] * (m + 1)
    dp[0] = 1
    for lim in a:
        pref = [0] * (m + 1)
        pref[0] = dp[0]
        for j in range(1, m + 1):
            pref[j] = (pref[j - 1] + dp[j]) % MOD
        newdp = [0] * (m + 1)
        for j in range(m + 1):
            low = j - lim - 1
            if low >= 0:
                val = (pref[j] - pref[low]) % MOD
            else:
                val = pref[j] % MOD
            newdp[j] = val
        dp = newdp
    return dp[m] % MOD

