def min_groups(w, n, prices):
    """Return the minimum number of groups needed to distribute all souvenirs
    into groups of at most two items whose total price does not exceed `w`."""
    if n == 0:
        return 0
    prices.sort()
    i, j = 0, n - 1
    groups = 0
    while i <= j:
        if i == j:
            groups += 1
            break
        if prices[i] + prices[j] <= w:
            i += 1
            j -= 1
        else:
            j -= 1
        groups += 1
    return groups

def hanoi_double_iterative(n: int) -> int:
    """Calculate the minimum number of moves required to solve the double-disc Hanoi Towers problem for n pairs of discs."""
    if n <= 0:
        return 0
    # Known closed form: 2^(n+1) - 2
    return (1 << (n + 1)) - 2
